          {text:"御手洗の住吉神社で目を止めたいのは、豪商の名前だけではない。呉市の地域資料には、境内を埋め立てる際、若胡子屋などの茶屋で働いた女性たちが砂持ちに参加し、遷宮の行列にも加わったと記されている。",refs:[2]},
          {text:"玉垣には、彼女たちの源氏名が刻まれているという。港の建設に関わった人々は、商人や大工だけではなかった。旅人を迎えた茶屋で働く女性たちも、この場所に名前を残した。",refs:[2]},
          {text:"ただし、華やかな行列の記録だけから、女性たちがどの程度自らの意思で参加したのか、暮らしがどうだったのかは分からない。石に名前があることの重みと、石から読み取れない生活の事情を、分けて考えたい。",refs:[2]}
