    provisionalConclusion:'神社名の分布から港同士の直接交流は断定できない。御手洗の造営には大阪の商人と大工が関わり、下津井には港問屋の記録、鞆には信仰の名を刻んだ常夜燈が残る。尾道では港の造成に伴う住吉神社の移転と、北国の地名を刻む石壁が確認できる。史料の性格を区別することで、海を渡った人・資金・技術のつながりと、港を造り替えた地域の仕事をそれぞれ検証できる。',
    openQuestions:['住吉・恵比須・金毘羅・祇園などを同じ項目でデータ化できるか','寄進者住所をGIS化して商圏を復元できるか','祭礼経路と旧港・市場・町境を重ねると何が見えるか'],
