          {text:'白壁を見ると、まず建物の美しさに目が向く。だが、この通りはもともと人に見せるために整えられた場所ではない。品物を売り買いし、荷を受け取り、帳面をつける町だった。店の正面だけでなく、その奥を想像してみたい。',refs:[1]}
