          {text:'鉄道が入浴客の移動を容易にしたことは確かだ。ただし、鉄道が実際に何人の客を新たに生んだかは、開業前後の利用記録を確かめる必要がある。ここで注目したいのは、港と城下町を結ぶ交通とは別に、温泉へ向かう道筋もまた鉄道の目的地になったことである。',refs:[]},
          {text:'道後は城下町に吸収されて個性を失ったのではない。独自の温泉地でありながら、都市の中心部から行きやすい場所になることで、むしろ役割を強めた。',refs:[]}
