    openQuestions:['三津浜・道後・城下町の人口と商業集積が鉄道開業前後でどう変化したか','伊予鉄道・道後鉄道の株主構成から地域資本の動きを追えるか','高浜港整備が三津浜の経済に与えた影響を定量化できるか'],
