          {text:'この位置なら、海上交通と港の出入りを同時に監視できる。岬は港を風から守るだけでなく、高所から航路を見張る軍事拠点にもなる。同じ地形が、港湾機能と防御機能の二つを生み出した。',refs:[]},
          {text:'城と港は別々の歴史ではない。交通上価値の高い港があったから、支配の拠点として城が必要になったと考えると、二つの配置が一つの因果でつながる。',refs:[]}
