          {text:'船が寄れば、荷を扱う人、商人、宿、食料、修理など陸上の仕事が必要になる。港を支配するだけでは経済は生まれない。船から人と物を陸へ移し、その需要を町の商いへ変えることで、初めて港町になる。',refs:[]},
          {text:'引田では、海から港へ、港から町へという距離が短い。小さな湾の背後に商家が集まるのは、船が持ち込む需要をすぐ町へ取り込むための配置だったと読むことができる。',refs:[]}
