          {text:'多度津や三原のように、鉄道が都市構造を大きく塗り替えた町もある。しかし引田は大都市化せず、城山、港、商家町という近世以来のスケールが比較的よく残った。',refs:[]},
          {text:'そのため現在の引田では、「なぜこの場所に港があり、その上に城があり、背後に町があるのか」を歩きながら理解できる。後世の都市化で因果が覆い隠されにくかったこと自体が、この町の価値になっている。',refs:[]}
