          {text:'見た目にはまだ「塩田」が残っている。しかし中の工程はすでに大きく変わっていた。江戸時代の方法を保存したから産地が続いたのではなく、産地を続けるために昔の方法を捨て始めていたのである。',refs:[]},
          {text:'ここで、地域産業の継承と伝統技術の保存は同じではないことが分かる。産業を残すには、技術を変えなければならない場合がある。',refs:[]}
