          {text:'翌1960年には赤穂海水株式会社を設立する。ここが大きな分岐点だった。個々の塩田を守ることより、製塩事業を一つの企業として残す道を選んだのである。',refs:[2]},
          {text:'もしこの時点で「赤穂の塩とは塩田で作るもの」と考えていたら、次の技術へ移る余地は小さかったはずだ。塩田ではなく事業を残す、と定義し直したことが重要だった。',refs:[]}
