    provisionalConclusion:'西宇和の柑橘園は、海面と石垣からの反射光などの自然条件を利用すると同時に、急傾斜地での重い作業を伴う。宮川早生と南柑20号など成熟期の異なる温州みかんが産地の収穫期をずらし、愛媛県全体では紅まどんな・甘平・紅プリンセスなどで春まで出荷期を延ばす品種開発が進む。ただし新しい品種は労働を不要にするのではなく、作業時期と管理方法を変える。',
