            "text": "岡山県では別の行き先も実用化されている。殻を海底に敷き、アマモや海底にすむ生物の環境を改善する使い方だ。県は2013年に施工の指針をまとめ、2022年には沖合の深い場所での試験結果も踏まえて改訂した。広島の殻がそのまま岡山に運ばれるという話ではなく、産地ごとに生まれた利用方法の一つである。",
