    provisionalConclusion:'広島の牡蠣殻は、海中保管・陸揚げ・粉砕を経て肥料や飼料として使われ、壁材として商品化され、コンセプトカーの内装部品にも採用された。岡山では別の取り組みとして海底環境の改善材にも使われている。販売商品と試作車の違い、広島と岡山の別々の処理体系は区別して描く。',
    openQuestions:['牡蠣殻の用途別利用量と余剰量はどう変化しているか','壁材・樹脂部品への利用はどこまで拡大しているか','保管・乾燥・加工・運搬を含めた環境負荷はどのくらいか'],
