    heroPhotoId:'photo-ehime-citrus-orchard',
    lead:"愛媛県南予の八幡浜は、豊後水道に面した漁業と水産加工の町だ。魚をさばけば、身のほかに骨や内臓、ウロコなどのアラが残る。では、そのアラはどこへ行くのだろう。愛媛には、アラを加工して養殖魚の餌に戻す仕事と、肥料に変えてみかん畑へ届ける仕事がある。海で生まれた残りものが、再び海の魚を育て、山の果実も育てている。",
