            "text": "八幡浜蒲鉾協同組合は、魚のアラや魚市場の売れ残りなどを受け入れ、脱水や粉砕、発酵、乾燥を経て「魚肥」をつくる仕組みを紹介している。魚肥はみかんなどの栽培に使われる。愛媛県の資料にある一日四トンという数字は、受入能力を示すもので、実際の処理量ではない。",
