    lead:"小豆島は、瀬戸内海を代表するオリーブの産地だ。丘の畑で育った実からオイルを搾ると、果肉や種などの搾りかすが残る。これを牛の飼料に変えたのは、島の畜産農家だった。オリーブを食べて育った牛は、やがて「小豆島オリーブ牛」という名前で売り出され、取り組みは香川県内へ広がっていった。オイルの産地から、思いがけないもう一つの食べ物が生まれた。",
