    openQuestions:['小豆島で年間に発生するオリーブ搾り粕量と飼料利用率はどの程度か','飼料化に必要な乾燥・加工コストと島外処分コストを比較できるか','醤油粕や剪定枝など他の副産物を含む島全体のマテリアルフローを描けるか'],
