    heroPhotoId:'photo-kinkai-solar',
    lead:"牛窓の近く、錦海湾の奥に広がる太陽光パネルの下は、かつて海だった。1950年代に湾を堤防で締め切り、海水をくみ出して塩田を造った。塩づくりが終わっても、この土地には水を外へ出し続ける仕事が残った。所有会社が破産し、排水ポンプが止まれば周囲の家々が浸水しかねない。瀬戸内市は土地を引き受け、発電所を誘致することで、安全管理の費用もまかなう道を選んだ。塩田が発電所になった理由は、日当たりのよさだけではなかった。",
