    provisionalConclusion:'日生の『さわらのこうこずし』は産卵期に来遊する魚を祝いの食卓へ迎えた文化。瀬戸内海の東西の水道からの回遊、春の中層水温、播磨灘・備讃瀬戸・燧灘の産卵場、稚魚の餌環境、流し網の漁の時期をつなげて記述する。『春が旬』は必ずしも最大脂肪量の季節を意味しない。2026年資源評価は食文化維持の留意事項として一段落に限定する。',
